export async function getTradePortfolioInstructionAsync<
  TAccountAuthority extends string,
  TAccountPortfolio extends string,
  TAccountExchange extends string,
  TAccountMarket extends string,
  TAccountPriceUpdate extends string,
  TProgramAddress extends Address = typeof RESULT_REGISTRY_PROGRAM_ADDRESS,
>(
  input: TradePortfolioAsyncInput<
    TAccountAuthority,
    TAccountPortfolio,
    TAccountExchange,
    TAccountMarket,
    TAccountPriceUpdate
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  TradePortfolioInstruction<
    TProgramAddress,
    TAccountAuthority,
    TAccountPortfolio,
    TAccountExchange,
    TAccountMarket,
    TAccountPriceUpdate
  >
> {
  // Program address.
  const programAddress =
    config?.programAddress ?? RESULT_REGISTRY_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    authority: { value: input.authority ?? null, isWritable: false },
    portfolio: { value: input.portfolio ?? null, isWritable: true },
    exchange: { value: input.exchange ?? null, isWritable: false },
    market: { value: input.market ?? null, isWritable: false },
    priceUpdate: { value: input.priceUpdate ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Original args.
  const args = { ...input };

  // Resolve default values.
  if (!accounts.portfolio.value) {
    accounts.portfolio.value = await findPortfolioPda({
      authority: expectAddress(accounts.authority.value),
    });
  }
  if (!accounts.exchange.value) {
    accounts.exchange.value = await findExchangePda();
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.authority),
      getAccountMeta(accounts.portfolio),
      getAccountMeta(accounts.exchange),
      getAccountMeta(accounts.market),
      getAccountMeta(accounts.priceUpdate),
    ],
    data: getTradePortfolioInstructionDataEncoder().encode(
      args as TradePortfolioInstructionDataArgs,
    ),
    programAddress,
  } as TradePortfolioInstruction<
    TProgramAddress,
    TAccountAuthority,
    TAccountPortfolio,
    TAccountExchange,
    TAccountMarket,
    TAccountPriceUpdate
  >);
}

